=== file: main.loom ===
// SupportEmailTriage: classify incoming support emails and fail closed.
// Inbound and outbound connectors are operator-configured placeholders; see README.md.

budget { tokens: 10000  calls: 12 }

tool IncomingEmail {
    use: openapi
    spec: env.INCOMING_EMAIL_SPEC
}

tool OrderSystem {
    use: openapi
    spec: env.ORDER_SYSTEM_SPEC
}

tool CustomerReply {
    use: email
    host: env.SMTP_HOST
    username: env.SMTP_USERNAME
    password: env.SMTP_PASSWORD
    from: env.SUPPORT_REPLY_FROM
    to: env.CUSTOMER_REPLY_TO
}

tool SupportQueue {
    use: webhook
    url: env.SUPPORT_QUEUE_URL
    format: json
}

agent OrderLookup {
    model: "gpt-6-luna"
    prompt: "order-lookup"
    temperature: 0.1
    tools: [OrderSystem]
    guard { pii: mask }
    output_schema: {
        status: string,
        essential_details: string
    }
}

agent OrderReply {
    model: "gpt-6-luna"
    prompt: "order-reply"
    temperature: 0.1
    tools: [CustomerReply, SupportQueue]
    approve: [CustomerReply, SupportQueue]
    guard { pii: mask }
    output_schema: {
        outcome: enum["sent", "queued", "unable"]
    }
}

intentclassifier EmailRoute {
    model: "gpt-6-luna"
    choose kind: order_status | refund | other
    confidence at least 0.8 else escalate
}

intentclassifier LookupReliability {
    model: "gpt-6-luna"
    choose kind: reliable | unreliable
    confidence at least 0.8 else escalate
}

workflow Main(incoming_email_text, verified_order_reference, customer_reply_destination) {
    intentclassify EmailRoute on incoming_email_text -> email_route
        retry 1 backoff 2s timeout 30s
        on_failure {
            note "Classification failed or the budget was exhausted. The email needs Support reviewer attention; no customer reply was sent."
            halt "Email classification was unavailable; leave the email unprocessed for operator intervention."
        }

    alt (email_route.kind == "unsure") {
        delegate "Route this uncertain classification to SupportQueue for Support reviewer handling. Case category: uncertain classification. Order reference, if provided: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply or issue a refund." to OrderReply -> uncertain_route expecting {
            outcome: enum["sent", "queued", "unable"]
        } retry 1 backoff 2s timeout 30s on_failure {
            note "Support queue routing failed or has an unknown outcome. Do not retry the send; report this case for operator intervention."
            halt "Uncertain email could not be routed safely."
        }
        note "Uncertain classification routed for human handling: {uncertain_route.outcome}."
    } else {
        alt (email_route.kind == "refund") {
            delegate "Route this refund request to SupportQueue for Support reviewer handling and explicit review. Case category: refund. Order reference, if provided: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Never issue a refund and do not send a customer reply." to OrderReply -> refund_route expecting {
                outcome: enum["sent", "queued", "unable"]
            } retry 1 backoff 2s timeout 30s on_failure {
                note "Refund routing failed or has an unknown outcome. No refund was issued. Report this case for operator intervention."
                halt "Refund request could not be routed safely."
            }
            note "Refund request routed for human review: {refund_route.outcome}."
        } else {
            alt (email_route.kind == "other") {
                delegate "Route this other support email to SupportQueue for Support reviewer handling. Case category: other. Order reference, if provided: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply or issue a refund." to OrderReply -> other_route expecting {
                    outcome: enum["sent", "queued", "unable"]
                } retry 1 backoff 2s timeout 30s on_failure {
                    note "Support queue routing failed or has an unknown outcome. Report this case for operator intervention."
                    halt "Other email could not be routed safely."
                }
                note "Other email routed for human handling: {other_route.outcome}."
            } else {
                delegate "Look up order reference {verified_order_reference} in the existing approved order system. Use only the order reference; return verified status and essential order details only. If missing, ambiguous, or inconclusive, do not infer facts." to OrderLookup -> order_lookup_result expecting {
                    status: string,
                    essential_details: string
                } retry 1 backoff 2s timeout 30s on_failure {
                    delegate "Route this failed or inconclusive order lookup to SupportQueue for Support reviewer handling. Case category: order lookup failed. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> lookup_failure_route expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 1 backoff 2s timeout 30s on_failure {
                        note "Order lookup and support routing failed. Leave the email unprocessed and report it for operator intervention."
                        halt "Order lookup failed and fallback routing was unavailable."
                    }
                    note "Order lookup failed; routed for human handling: {lookup_failure_route.outcome}."
                }

                intentclassify LookupReliability on order_lookup_result -> lookup_reliability
                    retry 1 backoff 2s timeout 30s
                    on_failure {
                        delegate "Route this order-status case to SupportQueue because lookup reliability could not be assessed. Case category: reliability assessment failed. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> reliability_failure_route expecting {
                            outcome: enum["sent", "queued", "unable"]
                        } retry 1 backoff 2s timeout 30s on_failure {
                            note "Reliability assessment and support routing failed. Leave the email unprocessed and report it for operator intervention."
                            halt "Reliability assessment failed and fallback routing was unavailable."
                        }
                        note "Reliability assessment failed; routed for human handling: {reliability_failure_route.outcome}."
                    }

                alt (lookup_reliability.kind == "reliable") {
                    delegate "Prepare a concise order-status reply using only these verified details. Status: {order_lookup_result.status}. Essential details: {order_lookup_result.essential_details}. Destination: {customer_reply_destination}. Send the reply only if it can be confidently prepared from those verified details. If not, route the case to SupportQueue instead. Do not add unsupported facts, expose unnecessary data, or issue a refund." to OrderReply -> customer_reply_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 1 backoff 2s timeout 30s on_failure {
                        note "Customer reply send failed or has an unknown outcome. Do not retry the send; report it for operator intervention."
                        halt "Customer reply outcome is unknown; stop without sending another reply."
                    }
                    note "Order-status handling completed with outcome: {customer_reply_action.outcome}."
                } else {
                    delegate "Route this order-status case to SupportQueue because the lookup was unreliable or uncertain. Case category: unreliable order lookup. Verified lookup status, if any: {order_lookup_result.status}. Essential details, if any: {order_lookup_result.essential_details}. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> unreliable_lookup_route expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 1 backoff 2s timeout 30s on_failure {
                        note "Unreliable lookup could not be routed. Leave the email unprocessed and report it for operator intervention."
                        halt "Unreliable order lookup could not be routed safely."
                    }
                    note "Unreliable or uncertain lookup routed for human handling: {unreliable_lookup_route.outcome}."
                }
            }
        }
    }
}
