# Scripted workflow tests: no live model calls or network access.
script: main.loom
workflow: Main
cases:
  - name: ReliableOrderStatus
    input:
      incoming_email_text: "Where is order A123?"
      verified_order_reference: "A123"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: order_status }
      OrderLookup: { status: "shipped", essential_details: "Expected Friday" }
      LookupReliability: { kind: reliable }
      OrderReply: { outcome: sent }
    humans: ["yes", "yes"]
    tools:
      OrderSystem: { status: "shipped", essential_details: "Expected Friday" }
      CustomerReply: "sent"
    expect:
      asked: ["Approve", "Approve"]
      effects: { count: 1 }

  - name: UnreliableOrderLookup
    input:
      incoming_email_text: "Where is order A124?"
      verified_order_reference: "A124"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: order_status }
      OrderLookup: { status: "unknown", essential_details: "No verified status" }
      LookupReliability: { kind: unreliable }
      OrderReply: { outcome: queued }
    humans: ["yes", "yes"]
    tools:
      OrderSystem: { status: "unknown", essential_details: "No verified status" }
      SupportQueue: "queued"
    expect:
      asked: ["Approve", "Approve"]
      effects: { count: 1 }

  - name: RefundOver100
    input:
      incoming_email_text: "Please refund my $250 order."
      verified_order_reference: "A125"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: refund }
      OrderReply: { outcome: queued }
    humans: ["yes"]
    tools:
      SupportQueue: "queued"
    expect:
      asked: ["Approve"]
      effects: { count: 1 }
      never: ["delegate OrderLookup"]

  - name: RefundAtOrBelow100
    input:
      incoming_email_text: "Please refund my $25 order."
      verified_order_reference: "A126"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: refund }
      OrderReply: { outcome: queued }
    humans: ["yes"]
    tools:
      SupportQueue: "queued"
    expect:
      asked: ["Approve"]
      effects: { count: 1 }
      never: ["delegate OrderLookup"]

  - name: OtherEmail
    input:
      incoming_email_text: "I have a question about my account."
      verified_order_reference: ""
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: other }
      OrderReply: { outcome: queued }
    humans: ["yes"]
    tools:
      SupportQueue: "queued"
    expect:
      asked: ["Approve"]
      effects: { count: 1 }
      never: ["delegate OrderLookup"]

  - name: UnsureClassification
    input:
      incoming_email_text: "Something is wrong, but I am not sure what."
      verified_order_reference: ""
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: unsure }
      OrderReply: { outcome: queued }
    humans: ["yes"]
    tools:
      SupportQueue: "queued"
    expect:
      asked: ["Approve"]
      effects: { count: 1 }
      never: ["delegate OrderLookup"]

  - name: UnableToDraftConfidentReply
    input:
      incoming_email_text: "Where is order A127?"
      verified_order_reference: "A127"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: order_status }
      OrderLookup: { status: "in transit", essential_details: "Carrier data is incomplete" }
      LookupReliability: { kind: reliable }
      OrderReply: { outcome: queued }
    humans: ["yes", "yes"]
    tools:
      OrderSystem: { status: "in transit", essential_details: "Carrier data is incomplete" }
      SupportQueue: "queued"
    expect:
      asked: ["Approve", "Approve"]
      effects: { count: 1 }

  - name: OrderLookupFailure
    input:
      incoming_email_text: "Where is order A128?"
      verified_order_reference: "A128"
      customer_reply_destination: "customer-destination"
    models:
      EmailRoute: { kind: order_status }
      OrderReply: { outcome: queued }
    humans: ["yes"]
