// SupportEmailTriage: classify incoming support emails and fail closed.

budget { tokens: 10000  calls: 12 }

tool IncomingEmail {
    use: openapi
    spec: env.INCOMING_EMAIL_SPEC
    methods: "GET"
}

tool OrderSystem {
    use: openapi
    spec: env.ORDER_SYSTEM_SPEC
    methods: "GET"
}

tool CustomerReply {
    use: email
    host: env.SMTP_HOST
    username: env.SMTP_USERNAME
    password: env.SMTP_PASSWORD
    from: env.SUPPORT_REPLY_FROM
    to: env.CUSTOMER_REPLY_TO
}

tool SupportQueue {
    use: webhook
    url: env.SUPPORT_QUEUE_URL
    format: json
}

agent OrderLookup {
    model: "gpt-6-luna"
    prompt: "order-lookup"
    temperature: 0.1
    tools: [OrderSystem]
    guard { pii: mask }
    output_schema: {
        status: string,
        essential_details: string
    }
}

agent OrderReply {
    model: "gpt-6-luna"
    prompt: "order-reply"
    temperature: 0.1
    tools: [CustomerReply, SupportQueue]
    guard { pii: mask }
    output_schema: {
        outcome: enum["sent", "queued", "unable"]
    }
}

intentclassifier EmailRoute {
    model: "gpt-6-luna"
    choose kind: order_status | refund | other
    confidence at least 0.8 else escalate
    guard { pii: mask }
}

intentclassifier LookupReliability {
    model: "gpt-6-luna"
    choose kind: reliable | unreliable
    confidence at least 0.8 else escalate
    guard { pii: mask }
}

workflow Main(inbound_case_body, trusted_order_key, verified_recipient_address) {
    intentclassify EmailRoute on inbound_case_body -> route_assessment_record
        retry 1 backoff 2s timeout 30s
        on_failure {
            delegate "Route this unclassified support email to SupportQueue for Support reviewer handling. Case category: classification failed. Do not send a customer reply or issue a refund." to OrderReply -> classification_failure_route expecting {
                outcome: enum["sent", "queued", "unable"]
            } retry 0 backoff 2s timeout 30s on_failure {
                note "Classification and support queue routing failed. Leave the email unprocessed and report it for operator intervention."
                halt "Classification failed and fallback routing was unavailable."
            }
            human_prompt "Support reviewer: review and handle the queued email whose classification failed. Reply with the disposition after handling it." -> classification_reviewer_disposition
            return { outcome: "queued_for_human", reviewer_disposition: "{classification_reviewer_disposition}" }
        }

    alt (route_assessment_record.kind == "unsure") {
        delegate "Route this uncertain classification to SupportQueue for Support reviewer handling. Case category: uncertain classification. Do not send a customer reply or issue a refund." to OrderReply -> uncertain_case_route expecting {
            outcome: enum["sent", "queued", "unable"]
        } retry 0 backoff 2s timeout 30s on_failure {
            note "Support queue routing failed or has an unknown outcome. Do not retry the send; report this case for operator intervention."
            halt "Uncertain email could not be routed safely."
        }
        human_prompt "Support reviewer: review and handle the queued email with an uncertain classification. Reply with the disposition after handling it." -> uncertain_reviewer_disposition
        return { outcome: "queued_for_human", reviewer_disposition: "{uncertain_reviewer_disposition}" }
    } else {
        alt (route_assessment_record.kind == "refund") {
            delegate "Route this refund request to SupportQueue for Support reviewer handling and explicit review. Case category: refund. Never issue a refund and do not send a customer reply." to OrderReply -> refund_case_route expecting {
                outcome: enum["sent", "queued", "unable"]
            } retry 0 backoff 2s timeout 30s on_failure {
                note "Refund routing failed or has an unknown outcome. No refund was issued. Report this case for operator intervention."
                halt "Refund request could not be routed safely."
            }
            human_prompt "Support reviewer: review this queued refund request, including any request of $100 or less. Reply with the disposition after handling it; no refund has been issued." -> refund_reviewer_disposition
            return { outcome: "queued_for_human", reviewer_disposition: "{refund_reviewer_disposition}" }
        } else {
            alt (route_assessment_record.kind == "other") {
                delegate "Route this other support email to SupportQueue for Support reviewer handling. Case category: other. Do not send a customer reply or issue a refund." to OrderReply -> other_case_route expecting {
                    outcome: enum["sent", "queued", "unable"]
                } retry 0 backoff 2s timeout 30s on_failure {
                    note "Support queue routing failed or has an unknown outcome. Report this case for operator intervention."
                    halt "Other email could not be routed safely."
                }
                human_prompt "Support reviewer: review and handle the queued other support email. Reply with the disposition after handling it." -> other_reviewer_disposition
                return { outcome: "queued_for_human", reviewer_disposition: "{other_reviewer_disposition}" }
            } else {
                delegate "Look up order reference {trusted_order_key} in the existing approved order system. Use only that reference; return verified status and essential order details only. If missing, ambiguous, or inconclusive, do not infer facts." to OrderLookup -> verified_lookup_record expecting {
                    status: string,
                    essential_details: string
                } retry 1 backoff 2s timeout 30s on_failure {
                    delegate "Route this failed or inconclusive order lookup to SupportQueue for Support reviewer handling. Case category: order lookup failed. Do not send a customer reply." to OrderReply -> lookup_failure_case_route expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Order lookup and support routing failed. Leave the email unprocessed and report it for operator intervention."
                        halt "Order lookup failed and fallback routing was unavailable."
                    }
                    human_prompt "Support reviewer: handle the queued case because the order lookup failed. Reply with the disposition after handling it." -> lookup_failure_reviewer_disposition
                    return { outcome: "queued_for_human", reviewer_disposition: "{lookup_failure_reviewer_disposition}" }
                }

                intentclassify LookupReliability on verified_lookup_record -> lookup_confidence_record
                    retry 1 backoff 2s timeout 30s
                    on_failure {
                        delegate "Route this order-status case to SupportQueue because lookup reliability could not be assessed. Case category: reliability assessment failed. Do not send a customer reply." to OrderReply -> reliability_failure_case_route expecting {
                            outcome: enum["sent", "queued", "unable"]
                        } retry 0 backoff 2s timeout 30s on_failure {
                            note "Reliability assessment and support routing failed. Leave the email unprocessed and report it for operator intervention."
                            halt "Reliability assessment failed and fallback routing was unavailable."
                        }
                        human_prompt "Support reviewer: handle the queued case because lookup reliability could not be assessed. Reply with the disposition after handling it." -> reliability_failure_reviewer_disposition
                        return { outcome: "queued_for_human", reviewer_disposition: "{reliability_failure_reviewer_disposition}" }
                    }

                alt (lookup_confidence_record.kind == "reliable") {
                    delegate "Prepare a concise order-status reply using only these verified details. Status: {verified_lookup_record.status}. Essential details: {verified_lookup_record.essential_details}. Send only to the supplied verified recipient. Send the reply only if it can be confidently prepared from those verified details. If not, route the case to SupportQueue instead. Do not add unsupported facts, expose unnecessary data, or issue a refund. Recipient: {verified_recipient_address}." to OrderReply -> customer_status_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Customer reply send failed or has an unknown outcome. Do not retry the send; report it for operator intervention."
                        halt "Customer reply outcome is unknown; stop without sending another reply."
                    }
                    alt (customer_status_action.outcome == "queued") {
                        human_prompt "Support reviewer: handle the queued order-status case because a confident customer reply could not be prepared. Reply with the disposition after handling it." -> draft_failure_reviewer_disposition
                        return { outcome: "queued_for_human", reviewer_disposition: "{draft_failure_reviewer_disposition}" }
                    } else {
                        alt (customer_status_action.outcome == "sent") {
                            return { outcome: "customer_reply_sent" }
                        } else {
                            delegate "Route this order-status case to SupportQueue because a confident reply could not be prepared. Case category: unable to draft confidently. Do not send a customer reply." to OrderReply -> draft_failure_case_route expecting {
                                outcome: enum["sent", "queued", "unable"]
                            } retry 0 backoff 2s timeout 30s on_failure {
                                note "The reply could not be prepared and support routing failed. Leave the email unprocessed and report it for operator intervention."
                                halt "Confident reply preparation and fallback routing failed."
                            }
                            human_prompt "Support reviewer: handle the queued order-status case because a confident reply could not be prepared. Reply with the disposition after handling it." -> unable_draft_reviewer_disposition
                            return { outcome: "queued_for_human", reviewer_disposition: "{unable_draft_reviewer_disposition}" }
                        }
                    }
                } else {
                    delegate "Route this order-status case to SupportQueue because the lookup was unreliable or uncertain. Case category: unreliable order lookup. Do not send a customer reply." to OrderReply -> unreliable_lookup_case_route expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Unreliable lookup could not be routed. Leave the email unprocessed and report it for operator intervention."
                        halt "Unreliable order lookup could not be routed safely."
                    }
                    human_prompt "Support reviewer: handle the queued order-status case because the lookup was unreliable. Reply with the disposition after handling it." -> unreliable_lookup_reviewer_disposition
                    return { outcome: "queued_for_human", reviewer_disposition: "{unreliable_lookup_reviewer_disposition}" }
                }
            }
        }
    }
}
