                delegate "Look up order reference {verified_order_reference} in the existing approved order system. Use only the order reference; return verified status and essential order details only. If missing, ambiguous, or inconclusive, do not infer facts." to OrderLookup -> order_lookup_result expecting {
                    status: string,
                    essential_details: string
                } retry 1 backoff 2s timeout 30s on_failure {
                    delegate "Route this failed or inconclusive order lookup to SupportQueue for Support reviewer handling. Case category: order lookup failed. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> lookup_failure_route expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 1 backoff 2s timeout 30s on_failure {
                        note "Order lookup and support routing failed. Leave the email unprocessed and report it for operator intervention."
                        halt "Order lookup failed and fallback routing was unavailable."
                    }
                    note "Order lookup failed; routed for human handling: {lookup_failure_route.outcome}."
                }

                intentclassify LookupReliability on order_lookup_result -> lookup_reliability
                    retry 1 backoff 2s timeout 30s
                    on_failure {
                        delegate "Route this order-status case to SupportQueue because lookup reliability could not be assessed. Case category: reliability assessment failed. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> reliability_failure_route expecting {
                            outcome: enum["sent", "queued", "unable"]
                        } retry 1 backoff 2s timeout 30s on_failure {
                            note "Reliability assessment and support routing failed. Leave the email unprocessed and report it for operator intervention."
                            halt "Reliability assessment failed and fallback routing was unavailable."
                        }
                        note "Reliability assessment failed; routed for human handling: {reliability_failure_route.outcome}."
                    }

                alt (lookup_reliability.kind == "reliable") {
                    delegate "Prepare a concise order-status reply using only these verified details. Status: {order_lookup_result.status}. Essential details: {order_lookup_result.essential_details}. Destination: {customer_reply_destination}. Send the reply only if it can be confidently prepared from those verified details. If not, route the case to SupportQueue instead. Do not add unsupported facts, expose unnecessary data, or issue a refund." to OrderReply -> customer_reply_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 1 backoff 2s timeout 30s on_failure {
