                        halt "Customer reply outcome is unknown; stop without sending another reply."
                    }
                    note "Order-status handling completed with outcome: {customer_reply_action.outcome}."
                } else {
                    delegate "Route this order-status case to SupportQueue because the lookup was unreliable or uncertain. Case category: unreliable order lookup. Verified lookup status, if any: {order_lookup_result.status}. Essential details, if any: {order_lookup_result.essential_details}. Order reference: {verified_order_reference}. Destination for case context: {customer_reply_destination}. Do not send a customer reply." to OrderReply -> unreliable_lookup_route expecting {
