workflow Main(customer_email_payload, trusted_order_key, verified_recipient_address, trusted_message_identifier) {
    intentclassify EmailRoute on customer_email_payload -> triage_classification_record
        retry 1 backoff 2s timeout 30s
        on_failure {
            delegate "Route this case to SupportQueue for Support reviewer handling. Case category: classification failed. Message identifier: {trusted_message_identifier}. Do not send a customer reply or issue a refund." to OrderReply -> classification_fallback_action expecting {
                outcome: enum["sent", "queued", "unable"]
            } retry 0 backoff 2s timeout 30s on_failure {
                note "Classification and support routing failed. Leave the email unprocessed and report it for operator intervention."
                halt "Classification failed and fallback routing was unavailable."
            }
            alt (classification_fallback_action.outcome == "queued") {
                human_prompt "Support reviewer: please review and handle this case. Confirm when it has been handled." -> classification_review_confirmation
                note "Support reviewer confirmation: {classification_review_confirmation}."
            } else {
                note "Classification failed and support routing did not succeed. Report this case for operator intervention."
                halt "Classification fallback routing did not succeed."
            }
        }

    alt (triage_classification_record.kind == "unsure") {
        delegate "Route this uncertain classification to SupportQueue for Support reviewer handling. Case category: uncertain classification. Message identifier: {trusted_message_identifier}. Do not send a customer reply or issue a refund." to OrderReply -> uncertain_case_action expecting {
            outcome: enum["sent", "queued", "unable"]
        } retry 0 backoff 2s timeout 30s on_failure {
            note "Support queue routing failed or has an unknown outcome. Do not retry the send; report this case for operator intervention."
            halt "Uncertain email could not be routed safely."
        }
        alt (uncertain_case_action.outcome == "queued") {
            human_prompt "Support reviewer: please review and handle this case. Confirm when it has been handled." -> uncertain_review_confirmation
            note "Support reviewer confirmation: {uncertain_review_confirmation}."
        } else {
            note "Uncertain classification could not be routed. Report this case for operator intervention."
            halt "Uncertain email routing did not succeed."
        }
    } else {
        alt (triage_classification_record.kind == "refund") {
            delegate "Route this refund request to SupportQueue for Support reviewer review and explicit approval. Case category: refund. Message identifier: {trusted_message_identifier}. Never issue a refund and do not send a customer reply." to OrderReply -> refund_case_action expecting {
                outcome: enum["sent", "queued", "unable"]
            } retry 0 backoff 2s timeout 30s on_failure {
                note "Refund routing failed or has an unknown outcome. No refund was issued. Report this case for operator intervention."
                halt "Refund request could not be routed safely."
            }
            alt (refund_case_action.outcome == "queued") {
                human_prompt "Support reviewer: review this refund request, including any request of $100 or less. Explicitly approve any refund over $100 before one is issued. Confirm when the case has been handled." -> refund_review_confirmation
                note "Support reviewer confirmation: {refund_review_confirmation}."
            } else {
                note "Refund request could not be routed. No refund was issued; report this case for operator intervention."
                halt "Refund routing did not succeed."
            }
        } else {
            alt (triage_classification_record.kind == "other") {
                delegate "Route this other support email to SupportQueue for Support reviewer handling. Case category: other. Message identifier: {trusted_message_identifier}. Do not send a customer reply or issue a refund." to OrderReply -> other_case_action expecting {
                    outcome: enum["sent", "queued", "unable"]
                } retry 0 backoff 2s timeout 30s on_failure {
                    note "Support queue routing failed or has an unknown outcome. Report this case for operator intervention."
                    halt "Other email could not be routed safely."
                }
                alt (other_case_action.outcome == "queued") {
                    human_prompt "Support reviewer: please review and handle this case. Confirm when it has been handled." -> other_review_confirmation
                    note "Support reviewer confirmation: {other_review_confirmation}."
                } else {
                    note "Other email could not be routed. Report this case for operator intervention."
                    halt "Other email routing did not succeed."
                }
            } else {
                delegate "Look up trusted order reference {trusted_order_key} in the existing approved order system. Use only that reference. Return verified status and essential order details only. If the reference is missing, ambiguous, or inconclusive, do not infer facts." to OrderLookup -> verified_order_snapshot expecting {
                    status: string,
                    essential_details: string
                } retry 1 backoff 2s timeout 30s on_failure {
                    delegate "Route this failed order lookup to SupportQueue for Support reviewer handling. Case category: order lookup failed. Message identifier: {trusted_message_identifier}. Do not send a customer reply." to OrderReply -> lookup_failure_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Order lookup and support routing failed. Leave the email unprocessed and report it for operator intervention."
                        halt "Order lookup failed and fallback routing was unavailable."
                    }
                    alt (lookup_failure_action.outcome == "queued") {
                        human_prompt "Support reviewer: please review and handle this failed order lookup. Confirm when it has been handled." -> lookup_failure_review_confirmation
                        note "Support reviewer confirmation: {lookup_failure_review_confirmation}."
                    } else {
                        note "Failed order lookup could not be routed. Report this case for operator intervention."
                        halt "Failed order lookup routing did not succeed."
                    }
                }

