                    on_failure {
                        delegate "Route this order-status case to SupportQueue because lookup reliability could not be assessed. Case category: reliability assessment failed. Message identifier: {trusted_message_identifier}. Do not send a customer reply." to OrderReply -> reliability_failure_action expecting {
                            outcome: enum["sent", "queued", "unable"]
                        } retry 0 backoff 2s timeout 30s on_failure {
                            note "Reliability assessment and support routing failed. Leave the email unprocessed and report it for operator intervention."
                            halt "Reliability assessment failed and fallback routing was unavailable."
                        }
                        alt (reliability_failure_action.outcome == "queued") {
                            human_prompt "Support reviewer: please review and handle this case because lookup reliability could not be assessed. Confirm when it has been handled." -> reliability_failure_review_confirmation
                            note "Support reviewer confirmation: {reliability_failure_review_confirmation}."
                        } else {
                            note "Reliability assessment could not be completed and the case was not routed. Report it for operator intervention."
                            halt "Reliability failure routing did not succeed."
                        }
                    }

                alt (lookup_confidence_record.kind == "reliable") {
                    delegate "Prepare a concise order-status reply using only these verified details. Status: {verified_order_snapshot.status}. Essential details: {verified_order_snapshot.essential_details}. Send to the supplied verified recipient: {verified_recipient_address}. Send only if the reply can be confidently prepared from these facts. If not, route the case to SupportQueue instead. Do not add unsupported facts, disclose unnecessary data, or issue a refund." to OrderReply -> customer_status_action expecting {
                        outcome: enum["sent", "queued", "unable"]
