            }
        } else {
            alt (triage_classification_record.kind == "other") {
                delegate "Route this other support email to SupportQueue for Support reviewer handling. Case category: other. Message identifier: {trusted_message_identifier}. Do not send a customer reply or issue a refund." to OrderReply -> other_case_action expecting {
                    outcome: enum["sent", "queued", "unable"]
                } retry 0 backoff 2s timeout 30s on_failure {
                    note "Support queue routing failed or has an unknown outcome. Report this case for operator intervention."
                    return { status: "operator_intervention" }
                }
                alt (other_case_action.outcome == "queued") {
                    human_prompt "Support reviewer: please review and handle this case. Confirm when it has been handled." -> other_review_confirmation
                    note "Support reviewer confirmation: {other_review_confirmation}."
                } else {
                    note "Other email could not be routed. Report this case for operator intervention."
                }
            } else {
                delegate "Look up trusted order reference {trusted_order_key} in the existing approved order system. Use only that reference. Return verified status and essential order details only. If the reference is missing, ambiguous, or inconclusive, do not infer facts." to OrderLookup -> verified_order_snapshot expecting {
                    status: string,
                    essential_details: string
                } retry 1 backoff 2s timeout 30s on_failure {
                    delegate "Route this failed order lookup to SupportQueue for Support reviewer handling. Case category: order lookup failed. Message identifier: {trusted_message_identifier}. Do not send a customer reply." to OrderReply -> lookup_failure_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Order lookup and support routing failed. Leave the email unprocessed and report it for operator intervention."
                        return { status: "operator_intervention" }
                    }
                    alt (lookup_failure_action.outcome == "queued") {
                        human_prompt "Support reviewer: please review and handle this failed order lookup. Confirm when it has been handled." -> lookup_failure_review_confirmation
                        note "Support reviewer confirmation: {lookup_failure_review_confirmation}."
                    } else {
                        note "Failed order lookup could not be routed. Report this case for operator intervention."
                    }
                    return { status: "operator_intervention" }
                }

                intentclassify LookupReliability on verified_order_snapshot -> lookup_confidence_record
                    retry 1 backoff 2s timeout 30s
                    on_failure {
                        delegate "Route this order-status case to SupportQueue because lookup reliability could not be assessed. Case category: reliability assessment failed. Message identifier: {trusted_message_identifier}. Do not send a customer reply." to OrderReply -> reliability_failure_action expecting {
                            outcome: enum["sent", "queued", "unable"]
                        } retry 0 backoff 2s timeout 30s on_failure {
                            note "Reliability assessment and support routing failed. Leave the email unprocessed and report it for operator intervention."
                            return { status: "operator_intervention" }
                        }
                        alt (reliability_failure_action.outcome == "queued") {
                            human_prompt "Support reviewer: please review and handle this case because lookup reliability could not be assessed. Confirm when it has been handled." -> reliability_failure_review_confirmation
                            note "Support reviewer confirmation: {reliability_failure_review_confirmation}."
                        } else {
                            note "Reliability assessment could not be completed and the case was not routed. Report it for operator intervention."
                        }
                        return { status: "operator_intervention" }
                    }

                alt (lookup_confidence_record.kind == "reliable") {
                    delegate "Prepare a concise order-status reply using only these verified details. Status: {verified_order_snapshot.status}. Essential details: {verified_order_snapshot.essential_details}. Send to the supplied verified recipient: {verified_recipient_address}. Send only if the reply can be confidently prepared from these facts. If not, route the case to SupportQueue instead. Do not add unsupported facts, disclose unnecessary data, or issue a refund." to OrderReply -> customer_status_action expecting {
                        outcome: enum["sent", "queued", "unable"]
                    } retry 0 backoff 2s timeout 30s on_failure {
                        note "Customer reply send failed or has an unknown outcome. Do not retry the send; report it for operator intervention."
                        return { status: "operator_intervention" }
                    }
                    alt (customer_status_action.outcome == "sent") {
                        note "Verified order-status reply sent."
                    } else {
                        alt (customer_status_action.outcome == "queued") {
                            human_prompt "Support reviewer: please review and handle this order-status case because a confident reply could not be prepared. Confirm when it has been handled." -> unable_reply_review_confirmation
                            note "Support reviewer confirmation: {unable_reply_review_confirmation}."
                        } else {
                            note "A confident reply could not be prepared and the case was not routed. Report it for operator intervention."
                        }
                    }
                } else {
                    delegate "Route this order-status case to SupportQueue because the lookup was unreliable or uncertain. Case category: unreliable order lookup. Message identifier: {trusted_message_identifier}. Do not send a customer reply." to OrderReply -> unreliable_lookup_action expecting {
